const inputItems = $input.all();

// Parse JSON strings, including escaped JSON strings
function parseJSON(value) {
    let result = value;

    for (let i = 0; i < 3; i++) {
        if (typeof result !== "string") break;

        result = result.trim();

        // Remove Markdown JSON code fences
        result = result.replace(/^```(?:json)?\s*/i, "")
                       .replace(/\s*```$/, "");

        try {
            result = JSON.parse(result);
        } catch (error) {
            throw new Error(
                "Unable to parse AI output as JSON: " + error.message
            );
        }
    }

    return result;
}

// Extract student records from different output formats
function extractRecords(data) {
    if (Array.isArray(data)) {
        return data.flatMap(extractRecords);
    }

    if (data && typeof data === "object") {
        // Handle common AI output array properties
        for (const key of ["students", "records", "data", "results"]) {
            if (Array.isArray(data[key])) {
                return data[key].flatMap(extractRecords);
            }
        }

        return [data];
    }

    return [];
}

// Clean individual student record
function cleanStudent(student) {

    const cleanText = (value) =>
        value == null ? "" : String(value).trim();

    const emailOriginal = cleanText(student.Email);

    const email = emailOriginal.toLowerCase();

    const emailValid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);

    const phone = cleanText(student.Phone).replace(/\D/g, "");

    const feePaid = String(student.Fee_Paid).toLowerCase() === "true";

    const enrolledDate = cleanText(student.Enrolled_Date);

    const validDate =
        /^\d{4}-\d{2}-\d{2}$/.test(enrolledDate) &&
        !isNaN(Date.parse(enrolledDate)) &&
        new Date(enrolledDate).toISOString().slice(0, 10) === enrolledDate;

    return {
        Student_ID: cleanText(student.Student_ID).toUpperCase(),

        Name: cleanText(student.Name)
            .replace(/\s+/g, " "),

        Email: emailValid ? email : null,

        Email_Original: emailOriginal,

        Email_Status: emailValid ? "Valid" : "Invalid",

        Phone: phone.length === 10 ? phone : null,

        Phone_Status: phone.length === 10 ? "Valid" : "Invalid",

        Course: cleanText(student.Course),

        Fee_Paid: feePaid,

        City: cleanText(student.City)
            .replace(/\s+/g, " "),

        Enrolled_Date: validDate ? enrolledDate : null,

        Date_Status: validDate ? "Valid" : "Invalid"
    };
}

// Process all incoming n8n items
const finalRecords = [];

for (const item of inputItems) {

    // Find AI output
    const rawData =
        item.json.output ??
        item.json.text ??
        item.json.response ??
        item.json.content ??
        item.json.result ??
        item.json;

    const parsedData = parseJSON(rawData);

    const records = extractRecords(parsedData);

    for (const student of records) {
        finalRecords.push({
            json: cleanStudent(student)
        });
    }
}

// Return cleaned records
return finalRecords;
